// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"bacitracin-neomycin":{"wirkmechanismus":"Zwei Antibiotika mit sich ergänzender Wirkung töten Bakterien auf der Haut ab. Bacitracin hemmt den Aufbau der Bakterienzellwand und wirkt vor allem gegen grampositive Keime wie Staphylokokken und Streptokokken. Neomycin, ein Aminoglykosid, blockiert die Eiweissherstellung am bakteriellen Ribosom und erfasst zusätzlich viele gramnegative Keime. Die Kombination wirkt bakterizid (abtötend), und Resistenzen entstehen seltener als mit einem Wirkstoff allein.","nebenwirkungen":{"unbekannt":["Allergische Hautreaktionen: Rötung, Juckreiz, Trockenheit, Ausschlag, Kontaktekzem (Neomycin-Allergie)","Kreuzallergie mit anderen Aminoglykosiden","Bei grossflächiger Anwendung oder auf offener Haut: Nierenschäden, Hörschäden und Gleichgewichtsstörungen","Muskelschwäche durch Hemmung der Nerv-Muskel-Übertragung bei Aufnahme ins Blut"]},"schwangerschaft":"Nur kleinflächig und nach ärztlicher Abwägung: Aminoglykoside können nach Aufnahme ins Blut das Gehör des Ungeborenen schädigen.","stillzeit":"Kleinflächige Anwendung nach Abwägung möglich; nicht auf die Brust auftragen.","hinweise":["Nur auf kleine Hautflächen und kurzzeitig anwenden; ohne Besserung nach wenigen Tagen ärztlich kontrollieren lassen.","Bei Juckreiz, Rötung oder Verschlechterung absetzen – möglicherweise eine Neomycin-Allergie, die bei künftigen Behandlungen angegeben werden sollte.","Nicht in die Augen und nicht in den Gehörgang bei verletztem Trommelfell bringen."],"darreichung":["Salbe","Puder"]},"baclofen":{"wirkmechanismus":"Entspannt krankhaft verkrampfte Muskeln, indem es überschiessende Nervenreflexe im Rückenmark dämpft. Baclofen ist ein Abkömmling des Botenstoffs GABA und aktiviert GABA-B-Rezeptoren. Dadurch wird die Freisetzung erregender Neurotransmitter gehemmt und die Übertragung mono- und polysynaptischer Reflexe im Rückenmark vermindert. Baclofen wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Schläfrigkeit (Sedierung)","Übelkeit"],"haeufig":["Benommenheit, Schwindel, Kopfschmerzen","Verwirrtheit, Euphorie, Depression, Halluzinationen, Albträume, Schlaflosigkeit","Muskelschwäche, Gangunsicherheit (Ataxie), Zittern, Muskelschmerzen","Atemdepression (abgeschwächte Atmung)","Sehstörungen, Augenzittern (Nystagmus)","Blutdruckabfall","Mundtrockenheit, Erbrechen, Verstopfung, Durchfall","Vermehrtes Wasserlassen, Bettnässen, vermehrtes Schwitzen, Hautausschlag"],"selten":["Kribbeln (Parästhesien), Sprechstörungen, Geschmacksstörungen","Bauchschmerzen, erhöhte Leberwerte","Harnverhalt, Erektionsstörungen"],"sehrSelten":["Unterkühlung (Hypothermie)"],"unbekannt":["Entzugssymptome nach abruptem Absetzen (Halluzinationen, Krampfanfälle, Fieber, Muskelsteifheit; bei der Pumpe lebensbedrohlich)","Langsamer Puls (Bradykardie)","Blutzuckeranstieg","Schlafapnoe","Suizidgedanken und Suizidversuche"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung; nach der Geburt sind Entzugskrämpfe beim Neugeborenen beschrieben.","stillzeit":"Geht bei Einnahme als Tablette nur in sehr geringen Mengen in die Muttermilch über; Stillen nach ärztlicher Abwägung möglich.","hinweise":["Nicht abrupt absetzen, sondern langsam ausschleichen – sonst Entzugssymptome bis zu Krampfanfällen. Bei der Pumpe die Nachfülltermine strikt einhalten.","Alkohol meiden.","Kann Müdigkeit, Schwindel und Sehstörungen verursachen – Vorsicht beim Autofahren.","Bei eingeschränkter Nierenfunktion deutlich niedriger dosieren; die Dosis wird langsam gesteigert."],"darreichung":["Tabletten","Intrathekale Injektions- bzw. Infusionslösung"]},"baldrian":{"wirkmechanismus":"Wirkt mild beruhigend und erleichtert das Einschlafen. Die Wirkung beruht auf dem Zusammenspiel mehrerer Inhaltsstoffe der Baldrianwurzel; diskutiert werden vor allem eine Verstärkung der hemmenden GABA-Signale im Gehirn (Valerensäure moduliert GABA-A-Rezeptoren) sowie Wirkungen an Adenosin-Rezeptoren. Der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (z. B. Übelkeit, Bauchkrämpfe)","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Bei Einschlafstörungen etwa eine halbe bis eine Stunde vor dem Zubettgehen einnehmen.","Die volle Wirkung entwickelt sich oft erst nach 2–4 Wochen regelmässiger Einnahme.","Kann die Reaktionsfähigkeit beeinträchtigen; Alkohol meiden.","Bessern sich die Beschwerden nach 2 Wochen nicht oder verschlimmern sie sich, ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Dragées","Tropfen","Tee"]},"baldrian-hopfen":{"wirkmechanismus":"Wirkt mild beruhigend und erleichtert das Einschlafen. Inhaltsstoffe der Baldrianwurzel wie die Valerensäure verstärken vermutlich die hemmenden GABA-Signale im Gehirn; Hopfen wirkt ergänzend beruhigend. Für den Kombinationsextrakt werden zudem Wirkungen an Adenosin- und Melatoninrezeptoren diskutiert. Der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (z. B. Übelkeit, Bauchkrämpfe)","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Bei Einschlafstörungen etwa eine halbe bis eine Stunde vor dem Zubettgehen einnehmen.","Die volle Wirkung entwickelt sich oft erst nach 2–4 Wochen regelmässiger Einnahme.","Kann die Reaktionsfähigkeit beeinträchtigen; Alkohol meiden.","Bessern sich die Beschwerden nach 2 Wochen nicht oder verschlimmern sie sich, ärztlichen Rat einholen."],"darreichung":["Filmtabletten"]},"beclometason":{"wirkmechanismus":"Hemmt die Entzündung in den Bronchien und macht sie weniger reizbar. Beclometasondipropionat ist ein Prodrug: in der Lunge wird es durch Esterasen zum stark wirksamen Beclometason-17-monopropionat gespalten, das an Glukokortikoid-Rezeptoren bindet. Dadurch werden die Bildung von Entzündungsbotenstoffen und die Einwanderung von Entzündungszellen vermindert. Die Wirkung baut sich über Tage bis Wochen auf; es ist kein Mittel gegen akute Anfälle.","nebenwirkungen":{"haeufig":["Mundsoor (Pilzinfektion in Mund und Rachen)","Heiserkeit","Rachenreizung"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Nesselsucht, Juckreiz, Rötung)"],"sehrSelten":["Angioödem (Schwellung von Augen, Gesicht, Lippen, Rachen), Atemnot, Anaphylaxie","Paradoxer Bronchospasmus","Systemische Kortisonwirkungen: Nebennierenunterdrückung, Cushing-Syndrom, Wachstumsverzögerung bei Kindern, Abnahme der Knochendichte, grauer und grüner Star"],"unbekannt":["Psychomotorische Überaktivität, Schlafstörungen, Angst, Depression, Aggressivität (v. a. bei Kindern)","Verschwommensehen"]},"schwangerschaft":"Nur nach ärztlicher Nutzen-Risiko-Abwägung; eine gute Asthmakontrolle ist für Mutter und Kind wichtig, und mit inhaliertem Beclometason liegen langjährige Erfahrungen vor.","stillzeit":"Ein Übergang in die Muttermilch in geringen Mengen ist anzunehmen; bei inhalierten Dosen ist ein Risiko für den Säugling unwahrscheinlich – Anwendung nach ärztlicher Abwägung.","hinweise":["Regelmässig anwenden, auch bei Beschwerdefreiheit; die volle Wirkung tritt erst nach einigen Tagen ein.","Nach dem Inhalieren den Mund ausspülen oder vor dem Essen inhalieren – beugt Mundsoor und Heiserkeit vor.","Nicht abrupt absetzen; nach Umstellung von Kortisontabletten bei Operationen oder schweren Infekten die frühere Kortisonbehandlung angeben.","Bei Kindern unter Langzeittherapie das Längenwachstum regelmässig kontrollieren lassen."],"darreichung":["Dosieraerosol","Atemzugausgelöstes Dosieraerosol (Autohaler)","Pulver zur Inhalation (Kombipräparat)"]},"benfotiamin":{"wirkmechanismus":"Liefert Vitamin B1 (Thiamin), das der Körper für die Energiegewinnung aus Kohlenhydraten und für die Funktion der Nerven braucht. Benfotiamin ist eine fettlösliche Vorstufe: Im Darm entsteht daraus S-Benzoylthiamin, das besser aufgenommen wird als wasserlösliche Thiaminsalze und im Körper zu Thiamin umgewandelt wird. Dessen aktive Form Thiaminpyrophosphat ist Coenzym wichtiger Enzyme des Zuckerstoffwechsels (Pyruvatdehydrogenase, Alpha-Ketoglutaratdehydrogenase, Transketolase).","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)"],"unbekannt":["Magen-Darm-Beschwerden wie Übelkeit"]},"schwangerschaft":"Der Tagesbedarf an Vitamin B1 ist in der Schwangerschaft erhöht und soll gedeckt werden. Höhere Dosen nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung, da Daten fehlen.","stillzeit":"Thiamin geht in die Muttermilch über; höhere Dosen nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung.","hinweise":["Unzerkaut mit etwas Flüssigkeit einnehmen.","Alkohol und grosse Mengen schwarzer Tee vermindern die Aufnahme von Vitamin B1.","Anhaltende Missempfindungen oder Taubheit in Händen und Füssen ärztlich abklären lassen – nicht jede Nervenschädigung beruht auf einem Vitamin-B1-Mangel."],"darreichung":["Tabletten"]},"benzoylperoxid":{"wirkmechanismus":"Wirkt gegen die an der Akne beteiligten Bakterien und löst verhornte Hautschüppchen. Benzoylperoxid zerfällt in der Haut zu Benzoesäure und setzt dabei reaktiven Sauerstoff frei, der Cutibacterium acnes (früher Propionibacterium acnes) abtötet – Resistenzen entstehen dabei nicht, weshalb es mit Antibiotika zum Auftragen kombiniert wird. Zusätzlich wirkt es schälend (keratolytisch) und mitesserlösend (komedolytisch) und vermindert freie Fettsäuren im Talg.","nebenwirkungen":{"sehrHaeufig":["Brennen der Haut","Rötung (Erythem)","Schuppung (Hautabschälung)","Trockene Haut"],"haeufig":["Juckreiz","Hautschmerzen, Stechen","Hautreizung (irritative Kontaktdermatitis)"],"gelegentlich":["Allergische Kontaktdermatitis"],"unbekannt":["Schwellung des Gesichts","Schwere allergische Reaktionen (Anaphylaxie) mit Engegefühl im Hals, Atemnot oder Kreislaufschwäche"]},"schwangerschaft":"Benzoylperoxid allein kann nach ärztlicher Abwägung angewendet werden, da nur wenig in den Körper gelangt. Die Kombination mit Adapalen (Epiduo) ist in der Schwangerschaft kontraindiziert.","stillzeit":"Kann angewendet werden; nicht auf die Brust auftragen, damit der Säugling nicht damit in Kontakt kommt.","hinweise":["Bleicht Haare, Augenbrauen, Kleidung, Handtücher und Bettwäsche – Kontakt vermeiden und nach dem Auftragen die Hände waschen.","Mit niedriger Konzentration oder seltener Anwendung beginnen; anfängliche Rötung und Schuppung lassen meist nach.","Sonnenschutz verwenden; nicht auf verletzte Haut auftragen."],"darreichung":["Gel"]},"benzydamin":{"wirkmechanismus":"Lindert Schmerzen und Entzündung direkt an der Schleimhaut von Mund und Rachen. Benzydamin ist ein Indazol-Abkömmling, der im Gegensatz zu klassischen NSAR die Prostaglandinbildung nur schwach hemmt. Es vermindert die Bildung entzündungsfördernder Botenstoffe wie Tumornekrosefaktor-alpha und Interleukin-1-beta und stabilisiert Zellmembranen; dadurch wirkt es zusätzlich leicht örtlich betäubend. Bei Anwendung im Mund gelangt nur wenig Wirkstoff ins Blut.","nebenwirkungen":{"gelegentlich":["Lichtempfindlichkeit der Haut (Photosensibilität)"],"selten":["Brennen im Mund","Mundtrockenheit","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"],"sehrSelten":["Laryngospasmus (Verkrampfung des Kehlkopfs)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Taubheitsgefühl im Mund (orale Hypästhesie)"]},"schwangerschaft":"Erfahrungen fehlen; in der Schwangerschaft nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Erfahrungen fehlen; in der Stillzeit nur nach ärztlicher Rücksprache anwenden.","hinweise":["Lösung nach dem Gurgeln oder Spülen ausspucken, nicht schlucken.","Lutschtabletten langsam im Mund zergehen lassen, nicht kauen oder schlucken.","Ohne ärztlichen Rat nicht länger als 7 Tage anwenden."],"darreichung":["Lösung zum Gurgeln und Spülen","Rachenspray","Lutschtabletten"]},"benzylpenicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Benzylpenicillin blockiert die Penicillin-bindenden Proteine (Transpeptidasen) und damit die Quervernetzung des Peptidoglykans; sich teilende Bakterien gehen zugrunde (bakterizide Wirkung). Es wirkt sehr stark gegen Streptokokken, Pneumokokken, Meningokokken, Treponemen (Syphilis-Erreger), Clostridien und Borrelien, wird aber von Beta-Laktamasen, etwa der meisten Staphylokokken, zerstört. Da es von der Magensäure abgebaut wird, muss es gespritzt werden; die Ausscheidung erfolgt rasch über die Niere.","nebenwirkungen":{"haeufig":["Allergische Hautreaktionen (Ausschlag, Nesselsucht, Juckreiz)"],"selten":["Anaphylaxie (schwere allergische Reaktion bis zum Kreislaufschock)","Angioödem (Schwellung von Gesicht und Rachen)"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Interstitielle Nephritis (Nierenentzündung)","Pseudomembranöse Kolitis (schwere Darmentzündung)"],"unbekannt":["Krampfanfälle, Muskelzuckungen, Verwirrtheit bei sehr hohen Dosen oder eingeschränkter Nierenfunktion","Blutbildveränderungen (Neutropenie, Thrombozytopenie, Eosinophilie)","Elektrolytstörungen (zu viel Natrium oder Kalium) bei hohen Dosen","Jarisch-Herxheimer-Reaktion bei Syphilis oder Borreliose","Venenreizung (Phlebitis) an der Infusionsstelle","Übelkeit, Durchfall, Entzündung von Mundschleimhaut oder Zunge","Arzneimittelfieber, Serumkrankheit"]},"schwangerschaft":"Erlaubt, wenn eine Behandlung nötig ist; lange Erfahrung ohne Hinweise auf eine Schädigung des Kindes (z. B. Mittel der Wahl bei Syphilis in der Schwangerschaft).","stillzeit":"Erlaubt; nur geringe Mengen gehen in die Muttermilch über (beim Säugling Durchfall oder Sensibilisierung möglich).","hinweise":["Wird im Spital oder in der Praxis als Injektion oder Infusion gegeben.","Eine frühere Penicillinallergie unbedingt vorher melden; nach der Gabe auf Ausschlag, Atemnot oder Schwindel achten.","Fieber und Schüttelfrost wenige Stunden nach Beginn einer Syphilisbehandlung sind meist eine harmlose Jarisch-Herxheimer-Reaktion – trotzdem ärztlich melden."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"berotralstat":{"wirkmechanismus":"Verhindert die übermässige Bildung von Bradykinin, das beim erblichen Angioödem die Schwellungen auslöst. Berotralstat ist ein kleines Molekül, das eingenommen wird und das Enzym Plasmakallikrein hemmt. Damit wird die Spaltung von hochmolekularem Kininogen zu Bradykinin gebremst, und die Attacken werden seltener. Berotralstat ist Substrat von P-Glykoprotein und BCRP und hemmt selbst mässig CYP3A4 und CYP2D6 sowie P-Glykoprotein.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Durchfall","Kopfschmerzen"],"haeufig":["Erbrechen","Sodbrennen (gastroösophagealer Reflux)","Blähungen","Hautausschlag","Erhöhte Leberwerte (ALT, AST)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Berotralstat in die Muttermilch übergeht (bei Tieren ja); Nutzen und Risiko ärztlich abwägen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Für akute Attacken trotzdem immer ein Notfallmedikament mitführen.","Vor jeder neuen Medikation Wechselwirkungen in der Apotheke prüfen lassen."],"darreichung":["Hartkapseln"]},"betahistin":{"wirkmechanismus":"Soll bei Menière-Krankheit die Häufigkeit und Stärke der Schwindelanfälle vermindern. Betahistin ist ein Histamin-Analogon: schwacher Agonist an H1-Rezeptoren und starker Antagonist an H3-Rezeptoren. Es verbessert vermutlich die Durchblutung im Innenohr und dämpft die Aktivität der Gleichgewichtskerne im Hirnstamm. Es wird rasch durch Monoaminoxidasen zum unwirksamen Abbauprodukt 2-Pyridylessigsäure abgebaut.","nebenwirkungen":{"haeufig":["Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Kopfschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Leichte Magenbeschwerden (Erbrechen, Bauchschmerzen, Blähungen)","Hautreaktionen (Angioödem, Nesselsucht, Ausschlag, Juckreiz)"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Betahistin in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Mit dem Essen einnehmen (bessere Magenverträglichkeit).","Die Wirkung kann sich erst nach einigen Wochen zeigen."],"darreichung":["Tabletten"]},"betain":{"wirkmechanismus":"Senkt den Spiegel der schädlichen Aminosäure Homocystein im Blut. Betain liefert eine Methylgruppe, mit der das Enzym Betain-Homocystein-Methyltransferase in Leber und Niere Homocystein zu Methionin umbaut (Remethylierung). Dieser Weg umgeht den gestörten Abbau beziehungsweise die gestörte folat- und Vitamin-B12-abhängige Remethylierung. Bei Cystathionin-beta-Synthase-Mangel steigt dadurch das Methionin im Blut an.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Methioninspiegel im Blut"],"gelegentlich":["Hirnödem (Hirnschwellung)","Appetitlosigkeit","Unruhe, Reizbarkeit","Durchfall, Übelkeit, Erbrechen, Magenbeschwerden, Zungenentzündung","Haarausfall, Nesselsucht, ungewöhnlicher Hautgeruch","Harninkontinenz"]},"schwangerschaft":"Nur wenige Daten. Anwendung nur, wenn eindeutig nötig, mit engmaschiger Kontrolle von Methionin und Homocystein.","stillzeit":"Nicht bekannt, ob Betain vermehrt in die Muttermilch übergeht. Anwendung nur nach ärztlicher Abwägung.","hinweise":["Pulver mit dem beigelegten Messlöffel abmessen, in Wasser, Saft, Milch oder Säuglingsnahrung auflösen oder unter das Essen mischen und sofort einnehmen.","Diät und ergänzende Vitamine (B6, B12, Folsäure) wie verordnet weiterführen.","Methionin- und Homocysteinspiegel regelmässig kontrollieren lassen.","Flasche nach Gebrauch gut verschliessen (Pulver zieht Feuchtigkeit an)."],"darreichung":["Pulver zum Einnehmen"]},"betamethason":{"wirkmechanismus":"Hemmt Entzündungen, allergische Reaktionen und überschiessende Immunreaktionen stark. Betamethason ist ein synthetisches Glukokortikoid, etwa 25- bis 30-mal stärker entzündungshemmend als Cortisol und praktisch ohne salzbindende Wirkung. Über den Glukokortikoid-Rezeptor im Zellinneren unterdrückt es die Bildung von Entzündungsbotenstoffen (z. B. Prostaglandine, Zytokine) und die Aktivität von Immunzellen. Als Valerat oder Dipropionat wirkt es auf der Haut stark (Klasse III); in Depotspritzen sorgt ein schwer lösliches Ester für eine Wirkung über mehrere Wochen.","nebenwirkungen":{"haeufig":["Juckreiz, Brennen oder Schmerzen an der Auftragsstelle (Haut)"],"sehrSelten":["Hautverdünnung (Atrophie), Dehnungsstreifen, erweiterte Äderchen, Pigmentveränderungen, vermehrte Behaarung (äusserliche Anwendung)","Allergische Kontaktdermatitis, Verschlechterung der Hauterkrankung, pustulöse Psoriasis (äusserliche Anwendung)","Bei grossflächiger oder langer Anwendung auf der Haut: Unterdrückung der Nebennieren, Cushing-Zeichen, Wachstumsverzögerung bei Kindern"],"unbekannt":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Zyklusstörungen (Tabletten, Injektion)","Erhöhter Blutzucker, Wassereinlagerungen, Bluthochdruck, Kaliummangel","Osteoporose, Muskelschwäche, Knochennekrose, Magen-Darm-Geschwüre","Erhöhte Infektanfälligkeit, Verschleierung von Infektionszeichen","Psychische Veränderungen: Schlafstörungen, Euphorie, Depression, Psychose","Grauer oder grüner Star, verschwommenes Sehen","Hautverdünnung und helle Flecken an der Einstichstelle; vorübergehende Gelenkreizung nach Gelenkinjektion","Anaphylaktische Reaktionen (Injektion)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; bei langer, hoch dosierter Anwendung sind Wachstumsverzögerung des Kindes und eine Nebennierenunterfunktion beim Neugeborenen möglich. Bei drohender Frühgeburt wird Betamethason gezielt zur Förderung der kindlichen Lungenreife eingesetzt. Auf der Haut nur kleinflächig und kurz.","stillzeit":"Geht in geringen Mengen in die Muttermilch über: kurzfristige oder äusserliche Anwendung nach Abwägung möglich, nicht auf die Brust auftragen; bei hohen Dosen über längere Zeit ärztliche Abwägung.","hinweise":["Stark wirksame Kortisoncremes (Klasse III) nicht ohne ärztliche Anweisung im Gesicht, in Hautfalten, im Genitalbereich oder unter luftdichten Verbänden anwenden.","Nach längerer Einnahme nicht abrupt absetzen, sondern schrittweise ausschleichen.","Bei Diabetes nach einer Depotspritze den Blutzucker häufiger kontrollieren.","HIV-Medikamente mit Ritonavir oder Cobicistat dem Arzt vor einer Kortisonbehandlung angeben."],"darreichung":["Tabletten","Depot-Injektionssuspension","Creme","Salbe","Lösung und Lotion zur Anwendung auf Haut und Kopfhaut"]},"bevacizumab":{"wirkmechanismus":"Hungert den Tumor aus, indem es die Bildung neuer Blutgefässe bremst. Bevacizumab ist ein humanisierter monoklonaler Antikörper, der den Wachstumsfaktor VEGF (vaskulärer endothelialer Wachstumsfaktor) bindet. VEGF kann dadurch nicht mehr an seine Rezeptoren auf Gefässzellen andocken. Die Tumorgefässe bilden sich zurück und neue entstehen kaum, was das Tumorwachstum verlangsamt.","nebenwirkungen":{"sehrHaeufig":["Hypertonie (Bluthochdruck)","Blutungen, vor allem Nasenbluten","Proteinurie (Eiweiss im Urin)","Müdigkeit und Schwäche","Durchfall, Übelkeit, Bauchschmerzen","Kopfschmerzen, Geschmacksstörungen","Wundheilungsstörungen","Ovarialinsuffizienz (Ausbleiben der Eierstockfunktion)"],"haeufig":["Magen-Darm-Perforation (Durchbruch)","Fisteln und Abszesse","Arterielle Thromboembolien (z. B. Herzinfarkt, Schlaganfall)","Venöse Thrombosen und Lungenembolie","Schwere Blutungen, z. B. Lungenblutung bei Lungenkrebs","Herzinsuffizienz (Herzschwäche)","Sepsis (Blutvergiftung)"],"gelegentlich":["Nephrotisches Syndrom (starker Eiweissverlust über die Niere)"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Sehstörungen, Krampfanfälle)","Nekrotisierende Fasziitis (schwere Weichteilinfektion)"],"sehrSelten":["Hypertensive Enzephalopathie (Hirnschädigung durch sehr hohen Blutdruck)"],"unbekannt":["Kiefernekrose","Durchbruch der Nasenscheidewand","Gallenblasenperforation","Thrombotische Mikroangiopathie"]},"schwangerschaft":"Kontraindiziert, da Fruchtschäden zu erwarten sind. Sichere Verhütung während und bis 6 Monate nach der letzten Dosis.","stillzeit":"Nicht stillen während der Behandlung und bis 6 Monate nach der letzten Dosis.","hinweise":["Blutdruck und Urin werden vor jeder Gabe kontrolliert.","Vor Operationen und Zahneingriffen die Behandlung angeben – ein Abstand von mindestens 4 Wochen ist nötig.","Starke Bauchschmerzen, Bluterbrechen, schwarzer Stuhl, Atemnot oder einseitige Lähmungen sofort ärztlich abklären lassen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"bicalutamid":{"wirkmechanismus":"Verhindert, dass männliche Hormone das Wachstum von Prostatakrebszellen anregen. Bicalutamid bindet kompetitiv an den Androgenrezeptor, ohne ihn zu aktivieren, und hemmt so die Wirkung von Testosteron und Dihydrotestosteron. Es wirkt peripher; der Testosteronspiegel kann bei alleiniger Gabe sogar leicht ansteigen. Wirksam ist hauptsächlich das R-Enantiomer, das sehr langsam abgebaut wird.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Gynäkomastie und Brustspannen (v. a. bei 150 mg)","Bauchschmerzen, Verstopfung, Übelkeit","Anämie (Blutarmut)","Blut im Urin","Schwindel","Schwäche, Ödeme"],"haeufig":["Erhöhte Leberwerte","Libidoabnahme, Erektionsstörungen","Depression, Schläfrigkeit","Hautausschlag, Juckreiz, Haarausfall oder vermehrte Behaarung","Appetitlosigkeit, Gewichtszunahme","Herzinsuffizienz, Herzinfarkt"],"gelegentlich":["Überempfindlichkeitsreaktionen, Angioödem, Nesselsucht","Interstitielle Lungenerkrankung"],"selten":["Leberversagen","Photosensibilität (Lichtempfindlichkeit)"],"unbekannt":["QT-Verlängerung"]},"schwangerschaft":"Nicht für Frauen bestimmt (kontraindiziert).","stillzeit":"Nicht für Frauen bestimmt (kontraindiziert).","hinweise":["Täglich zur gleichen Zeit einnehmen.","Leberwerte werden regelmässig kontrolliert; Gelbfärbung, dunkler Urin oder starke Müdigkeit sofort melden.","Bei Schwindel oder Schläfrigkeit nicht Auto fahren."],"darreichung":["Filmtabletten"]},"bictegravir-emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Bictegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Emtricitabin und Tenofovir (aus der Vorstufe Tenofoviralafenamid freigesetzt) werden in den Zellen zu ihren aktiven Formen phosphoryliert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Bictegravir hemmt zudem Nierentransporter (OCT2, MATE1), was den Kreatininwert leicht erhöht, ohne die Nierenfunktion zu verschlechtern.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit","Abnorme Träume","Depression","Müdigkeit"],"gelegentlich":["Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Angst, Schlafstörungen","Suizidgedanken oder Suizidversuch (vor allem bei psychischer Vorerkrankung)","Hautausschlag, Juckreiz, Nesselsucht, Angioödem","Gelenkschmerzen","Anämie","Erhöhtes Bilirubin"],"unbekannt":["Stevens-Johnson-Syndrom (Einzelfälle nach Markteinführung)"]},"schwangerschaft":"In der Schwangerschaft nach Abwägung durch die HIV-Fachperson; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko, im letzten Drittel sind die Spiegel aber tiefer – Viruslast engmaschig kontrollieren.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Calcium- und Eisenpräparate nur zeitversetzt bzw. zusammen mit einer Mahlzeit einnehmen.","Bei Hepatitis B nicht eigenmächtig absetzen.","Ein leichter Kreatininanstieg zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"bilastin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert so allergische Beschwerden an Nase, Augen und Haut. Bilastin ist ein hochselektiver Antagonist peripherer Histamin-H1-Rezeptoren ohne nennenswerte Bindung an andere Rezeptoren. Weil es vom Transportprotein P-Glykoprotein aus dem Gehirn hinausbefördert wird, macht es nicht müde. Es wird praktisch nicht verstoffwechselt und unverändert über Stuhl und Urin ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit"],"gelegentlich":["Schwindel, Müdigkeit","Appetitsteigerung, Gewichtszunahme","Angst, Schlaflosigkeit","Ohrgeräusche (Tinnitus)","EKG-Veränderungen (QT-Verlängerung, Rechtsschenkelblock, Sinusarrhythmie)","Bauchschmerzen, Übelkeit, Durchfall, Mundtrockenheit, Magenschleimhautentzündung","Juckreiz","Erhöhte Leberwerte"],"unbekannt":["Herzklopfen, Herzrasen","Überempfindlichkeitsreaktionen (Anaphylaxie, Angioödem, Atemnot, Hautausschlag)","Erbrechen"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber nicht anwenden.","stillzeit":"Nicht bekannt, ob Bilastin in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Nüchtern einnehmen: eine Stunde vor oder zwei Stunden nach einer Mahlzeit oder einem Fruchtsaft.","Macht in der Regel nicht müde; die eigene Reaktion vor dem Autofahren trotzdem prüfen."],"darreichung":["Tabletten"]},"bimatoprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem mehr Kammerwasser aus dem Auge abfliesst. Bimatoprost ist ein synthetisches Prostamid, chemisch mit dem Prostaglandin F2α verwandt. Es steigert sowohl den Abfluss über das Trabekelwerk als auch den uveoskleralen Abfluss, ohne die Bildung des Kammerwassers zu beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Rötung der Bindehaut (Bindehauthyperämie)"],"haeufig":["Verstärktes Wimpernwachstum (bei 0,3 mg/ml sehr häufig)","Punktförmige Hornhautentzündung","Augenreizung, Fremdkörpergefühl, Augenjucken, Augenschmerzen","Trockenes Auge","Dunkelfärbung der Haut um das Auge, verstärkte Behaarung","Rötung und Juckreiz der Lider"],"gelegentlich":["Dauerhaft dunklere Färbung der Iris","Verschwommenes Sehen, Augenermüdung","Schwellung von Bindehaut und Lidern","Kopfschmerzen","Übelkeit","Wimpernverlust"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Einsinken des Augenlids (Vertiefung der Lidfurche)","Asthma, Verschlechterung von Asthma oder COPD, Atemnot","Allergische Reaktionen an Auge und Haut","Blutdruckanstieg"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; ausreichende Erfahrungen beim Menschen fehlen.","stillzeit":"Ob Bimatoprost in die Muttermilch übergeht, ist nicht bekannt; Anwendung nur nach ärztlicher Abwägung, gegebenenfalls abstillen.","hinweise":["Einmal täglich (meist abends) eintropfen; häufigere Anwendung kann die Drucksenkung abschwächen.","Nach dem Eintropfen die Augen kurz schliessen und überschüssige Flüssigkeit von der Lidhaut abwischen (Haarwuchs und Hautverfärbung möglich).","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen; zu anderen Augentropfen 5 Minuten Abstand halten."],"darreichung":["Augentropfen","Augentropfen ohne Konservierungsmittel (Einzeldosen)"]},"bimatoprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei sich ergänzende Wege. Bimatoprost, ein synthetisches Prostamid (Prostaglandin-Analogon), verbessert den Abfluss des Kammerwassers über das Trabekelwerk und den uveoskleralen Weg. Timolol, ein nicht selektiver Betablocker, vermindert die Bildung von Kammerwasser im Ziliarkörper. Timolol kann nach Aufnahme über die Schleimhäute auch Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Augenrötung (Bindehauthyperämie)","Wimpernwachstum"],"haeufig":["Kopfschmerzen","Oberflächliche Hornhautentzündung, Hornhauterosion","Brennen, Stechen, Jucken, Fremdkörpergefühl, trockenes Auge, Augenschmerzen","Lidrötung, Lichtempfindlichkeit, Augenausfluss, Sehstörungen","Dunklere Lidhaut, vermehrtes Haarwachstum um das Auge","Schnupfen (Rhinitis)"],"gelegentlich":["Regenbogenhautentzündung (Iritis)","Bindehautschwellung, Lidschmerzen, Augenermüdung","Einwachsende Wimpern (Trichiasis)","Atemnot"],"unbekannt":["Langsamer Puls (Bradykardie), Herzrhythmusstörungen, Blutdruckabfall","Asthma, Bronchospasmus","Makulaödem (Netzhautschwellung)","Eingesunkene Augen (Vertiefung der Lidfurche)","Dauerhafte Braunfärbung der Iris","Schwindel, Schlafstörungen, Albträume, Müdigkeit","Allergische Reaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen (langsamer Puls, Unterzuckerung) überwachen.","stillzeit":"Timolol geht in die Muttermilch über, zu Bimatoprost fehlen Daten – in der Stillzeit nicht anwenden.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Überschüssige Tropfen von der Lidhaut abwischen, um Verfärbungen und Haarwuchs um das Auge zu vermindern.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"biotin":{"wirkmechanismus":"Biotin ist ein Vitamin, das für den Stoffwechsel von Fetten, Kohlenhydraten und Eiweissen nötig ist und das Wachstum von Haut, Haaren und Nägeln unterstützt. Es dient als Coenzym von Carboxylasen (z. B. Acetyl-CoA-Carboxylase, Pyruvatcarboxylase), die Kohlendioxid auf Stoffwechselprodukte übertragen. Ein echter Biotinmangel ist selten; er kommt z. B. bei angeborenem Biotinidase-Mangel, langer künstlicher Ernährung oder unter bestimmten Antiepileptika vor.","nebenwirkungen":{"sehrSelten":["Allergische Hautreaktionen (Nesselsucht)"]},"schwangerschaft":"Biotin in Dosen im Bereich des Tagesbedarfs ist unbedenklich; höhere Dosen nur nach ärztlicher Rücksprache, da wenige Daten vorliegen.","stillzeit":"Biotin geht in die Muttermilch über; höhere Dosen nur nach ärztlicher Rücksprache.","hinweise":["Vor Blutuntersuchungen die Biotin-Einnahme angeben; je nach Test wird empfohlen, Biotin einige Tage vorher zu pausieren.","Nägel und Haare wachsen langsam – eine Wirkung zeigt sich frühestens nach einigen Wochen bis Monaten."],"darreichung":["Tabletten"]},"biperiden":{"wirkmechanismus":"Stellt das Gleichgewicht zwischen den Botenstoffen Dopamin und Acetylcholin im Gehirn teilweise wieder her und vermindert so Zittern, Steifigkeit und Muskelkrämpfe. Biperiden blockiert zentrale Muskarinrezeptoren (bevorzugt M1) im Striatum, wo bei Dopaminmangel ein relatives Acetylcholin-Übergewicht besteht. Die periphere anticholinerge Wirkung erklärt Nebenwirkungen wie Mundtrockenheit, Verstopfung und Harnverhalt.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schwindel, Benommenheit","Unruhe, Erregung, Angst, Euphorie, Verwirrtheit, Halluzinationen, Gedächtnisstörungen (besonders bei höherer Dosis und älteren Menschen)","Mundtrockenheit, verminderte Schweissbildung","Akkommodationsstörungen, erweiterte Pupillen, Lichtempfindlichkeit, Auslösung eines Engwinkelglaukoms","Herzrasen (Tachykardie)","Verstopfung, Magenbeschwerden, Übelkeit","Störungen beim Wasserlassen bis Harnverhalt","Dyskinesien, Koordinations- und Sprechstörungen, Krampfanfälle"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; nicht stillen.","hinweise":["Nicht abrupt absetzen – Gefahr der Verschlechterung der Parkinson-Symptome oder von Entzugserscheinungen.","Bei Mundtrockenheit helfen zuckerfreie Kaugummis; bei Augenschmerzen, Harnverhalt oder Verwirrtheit ärztlich melden.","Bei Hitze auf Überwärmung achten (vermindertes Schwitzen).","Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Tabletten","Retardtabletten","Injektionslösung"]},"bisacodyl":{"wirkmechanismus":"Regt die Darmbewegung an und sorgt dafür, dass mehr Wasser im Darm bleibt, sodass der Stuhl weicher wird. Bisacodyl ist eine Vorstufe (Prodrug): Im Darm wird es durch Enzyme der Darmschleimhaut und Bakterien zum Wirkstoff BHPM (Bis-(p-hydroxyphenyl)-pyridyl-2-methan) umgewandelt. Dieser reizt die Nerven der Dickdarmschleimhaut, verstärkt die Peristaltik und hemmt die Rückaufnahme von Wasser und Salzen bzw. fördert deren Ausscheidung in den Darm. Die magensaftresistente Hülle verhindert eine Freisetzung im Magen.","nebenwirkungen":{"haeufig":["Bauchkrämpfe, Bauchschmerzen","Übelkeit","Durchfall"],"gelegentlich":["Erbrechen, Bauchbeschwerden","Blut im Stuhl (Hämatochezie)","Beschwerden und Brennen im Analbereich (Zäpfchen)","Schwindel"],"selten":["Überempfindlichkeitsreaktionen, Angioödem, Anaphylaxie","Dehydratation (Flüssigkeitsmangel)","Kolitis (Dickdarmentzündung), auch ischämische Kolitis","Kurze Ohnmacht (Synkope) beim Stuhlgang"]},"schwangerschaft":"Es sind keine schädlichen Wirkungen bekannt; dennoch nur nach ärztlicher Rücksprache und wenn Ernährungsmassnahmen nicht ausreichen.","stillzeit":"Der Wirkstoff geht nicht in nennenswertem Mass in die Muttermilch über; Anwendung in der Stillzeit möglich.","hinweise":["Dragées unzerkaut schlucken, nicht zusammen mit Milch oder Säurebindern; abends eingenommen wirken sie am nächsten Morgen.","Abführmittel nur kurzzeitig anwenden; bei länger dauernder Verstopfung ärztlich abklären lassen.","Für die Vorbeugung von Verstopfung sind ballaststoffreiche Ernährung, genügend Trinken und Bewegung erste Wahl."],"darreichung":["Magensaftresistente Dragées","Zäpfchen"]},"bismutsubcitrat-kalium-metronidazol-tetracyclin":{"wirkmechanismus":"Bekämpft den Magenkeim Helicobacter pylori mit drei Wirkstoffen gleichzeitig; das zusätzlich eingenommene Omeprazol senkt die Magensäure und verbessert die Wirkung. Bismut wirkt direkt antibakteriell, stört die Haftung der Bakterien an der Schleimhaut und schützt den Geschwürsgrund. Metronidazol wird im Bakterium zu reaktiven Produkten umgewandelt, die dessen Erbgut (DNA) schädigen. Tetracyclin hemmt die bakterielle Eiweisssynthese durch Bindung an die 30S-Untereinheit der Ribosomen. Die Kombination wirkt auch bei Keimen, die gegen Clarithromycin resistent sind.","nebenwirkungen":{"sehrHaeufig":["Schwarzfärbung des Stuhls (harmlos, durch Bismut)","Durchfall","Übelkeit","Geschmacksstörungen (Metallgeschmack)"],"haeufig":["Kopfschmerzen, Schwindel","Erbrechen, Bauchschmerzen, Verstopfung, Blähungen","Mundtrockenheit","Scheidenpilz","Schwäche, Müdigkeit","Erhöhte Leberwerte"],"gelegentlich":["Schläfrigkeit, Kribbeln oder Taubheitsgefühl, Zittern","Pilzinfektion im Mund (Soor)","Zungen- und Mundschleimhautentzündung, Zungenverfärbung","Appetitlosigkeit","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Pseudomembranöse Kolitis (schwere Darmentzündung durch Clostridioides difficile)","Anaphylaxie und schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom, DRESS)","Periphere Neuropathie, Enzephalopathie, Krampfanfälle, aseptische Meningitis","Schwere Leberschädigung","Lichtempfindlichkeit (Photosensibilisierung)","Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie)"]},"schwangerschaft":"Kontraindiziert: Tetracyclin schädigt Zähne und Knochen des ungeborenen Kindes, Metronidazol tritt in den kindlichen Kreislauf über.","stillzeit":"Kontraindiziert; Metronidazol und Tetracyclin gehen in die Muttermilch über.","hinweise":["Kapseln ganz, in aufrechter Haltung und mit einem grossen Glas Wasser schlucken, nicht im Liegen (Reizung der Speiseröhre).","Während der Behandlung und mindestens 3 Tage danach keinen Alkohol trinken.","Die Behandlung zusammen mit Omeprazol über die volle Dauer durchführen; nicht mit Milch einnehmen.","Starke Sonne und Solarium meiden; schwarzer Stuhl ist harmlos."],"darreichung":["Hartkapseln"]},"bisoprolol":{"wirkmechanismus":"Verlangsamt den Herzschlag und entlastet das Herz, indem es die Wirkung der Stresshormone am Herzen blockiert. Bisoprolol ist ein hochselektiver Hemmer der Beta-1-Rezeptoren ohne Eigenwirkung am Rezeptor; es senkt Herzfrequenz, Kontraktionskraft, Sauerstoffverbrauch und die Reninfreisetzung. Es wird je zur Hälfte in der Leber (u. a. CYP3A4) abgebaut und unverändert über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Bradykardie (langsamer Puls) – v. a. bei Behandlung der Herzinsuffizienz"],"haeufig":["Schwindel, Kopfschmerzen (v. a. zu Therapiebeginn)","Kältegefühl oder Taubheit in Händen und Füssen","Übelkeit, Erbrechen, Durchfall, Verstopfung","Müdigkeit, Erschöpfung","Verschlechterung einer Herzinsuffizienz, Blutdruckabfall (bei Herzinsuffizienz-Patienten)"],"gelegentlich":["AV-Überleitungsstörungen","Blutdruckabfall beim Aufstehen","Schlafstörungen, Depression","Bronchospasmus bei Asthma oder COPD","Muskelschwäche, Muskelkrämpfe"],"selten":["Albträume, Halluzinationen","Ohnmacht (Synkope)","Verminderter Tränenfluss (Kontaktlinsen)","Hörstörungen","Hepatitis, erhöhte Leberwerte, erhöhte Blutfette","Potenzstörungen","Überempfindlichkeitsreaktionen (Juckreiz, Rötung, Ausschlag)"],"sehrSelten":["Bindehautentzündung","Haarausfall","Auslösung oder Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (mögliche Wachstumsverzögerung des Kindes). Das Neugeborene auf langsamen Puls und Unterzuckerung überwachen.","stillzeit":"Nicht ausreichend untersucht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Nicht abrupt absetzen – schrittweise ausschleichen, besonders bei koronarer Herzkrankheit.","Bei Herzinsuffizienz wird die Dosis langsam über Wochen gesteigert; anfänglich können Beschwerden zunehmen.","Morgens unabhängig vom Essen einnehmen; Fahrtüchtigkeit kann zu Beginn und mit Alkohol beeinträchtigt sein."],"darreichung":["Filmtabletten"]},"bortezomib":{"wirkmechanismus":"Blockiert die «Müllabfuhr» der Zelle, sodass sich in Krebszellen schädliche Eiweisse anstauen und die Zellen absterben. Bortezomib hemmt reversibel die chymotrypsinähnliche Aktivität des 26S-Proteasoms. Dadurch werden regulatorische Proteine nicht mehr abgebaut, was unter anderem den Signalweg NF-κB hemmt und den programmierten Zelltod auslöst. Myelomzellen reagieren darauf besonders empfindlich.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie, Neutropenie, Anämie","Periphere Neuropathie (Kribbeln, Brennen, Taubheit)","Übelkeit, Erbrechen, Durchfall, Verstopfung","Appetitlosigkeit","Müdigkeit, Schwäche, Fieber","Muskelschmerzen"],"haeufig":["Hypotonie (tiefer Blutdruck), auch beim Aufstehen","Herpes zoster (Gürtelrose)","Lungenentzündung und andere Infektionen","Schwindel, Kopfschmerzen","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen)","Atemnot","Verschlechterung der Nierenfunktion"],"gelegentlich":["Herzinsuffizienz, Herzrhythmusstörungen","Tumorlysesyndrom","Leberfunktionsstörung","Blutungen (z. B. Magen-Darm)"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Akute diffuse infiltrative Lungenerkrankung","Ischämische Kolitis (Darmdurchblutungsstörung)","Schwere Hautreaktionen"],"sehrSelten":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)"]},"schwangerschaft":"Nicht anwenden. Frauen sollen während und bis 8 Monate, Männer bis 3 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Meist wird eine vorbeugende Behandlung gegen Gürtelrose (z. B. Aciclovir) verschrieben – regelmässig einnehmen.","Ausreichend trinken; bei Schwindel oder Ohnmachtsneigung nicht Auto fahren.","Kribbeln, Brennen oder Taubheit in Händen und Füssen früh melden."],"darreichung":["Pulver oder Lösung zur Injektion (unter die Haut oder in die Vene)"]},"bosentan":{"wirkmechanismus":"Erweitert die Lungengefässe und bremst deren krankhaften Umbau. Bosentan blockiert beide Endothelin-Rezeptoren (ETA und ETB) und hemmt so die Wirkung von Endothelin-1, das bei Lungenhochdruck vermehrt gebildet wird und Gefässe verengt, verdickt und vernarben lässt. Der Widerstand in den Lungengefässen sinkt, das rechte Herz wird entlastet und die Belastbarkeit verbessert sich.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Ödeme, Flüssigkeitsretention (Wassereinlagerungen)"],"haeufig":["Anämie (Blutarmut), Hämoglobinabfall","Erhöhte Leberwerte (Transaminasen)","Überempfindlichkeitsreaktionen (Hautentzündung, Juckreiz, Ausschlag)","Synkope (Ohnmacht), Herzklopfen","Gesichtsrötung (Flush), Blutdruckabfall","Verstopfte Nase","Sodbrennen (Reflux), Durchfall"],"gelegentlich":["Thrombozytopenie, Neutropenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Leberentzündung mit Gelbsucht"],"selten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Leberzirrhose, Leberversagen"],"unbekannt":["Verschwommenes Sehen"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Schwangerschaftstest vor Beginn und monatlich; zuverlässige Verhütung, wobei hormonelle Methoden allein nicht genügen.","stillzeit":"Nicht stillen – Bosentan geht in die Muttermilch über.","hinweise":["Leberwerte monatlich kontrollieren; bei Übelkeit, Erbrechen, Fieber, Bauchschmerzen, Gelbsucht oder dunklem Urin sofort ärztlich melden.","Frauen im gebärfähigen Alter: monatlicher Schwangerschaftstest und zuverlässige Verhütung (die Pille allein reicht nicht).","Rasche Gewichtszunahme oder Beinschwellungen melden (Flüssigkeitseinlagerung)."],"darreichung":["Filmtabletten","Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"botulinumtoxin-typ-a":{"wirkmechanismus":"Lähmt den behandelten Muskel oder die Schweissdrüse vorübergehend, indem es die Signalübertragung vom Nerv blockiert. Botulinumtoxin Typ A wird in die Nervenendigungen aufgenommen und spaltet dort das Protein SNAP-25, das für die Freisetzung von Acetylcholin nötig ist. Ohne Acetylcholin kann sich der Muskel nicht mehr zusammenziehen und die Schweissdrüse keinen Schweiss mehr bilden. Die Wirkung setzt nach einigen Tagen ein und lässt nach etwa 3–6 Monaten nach, wenn neue Nervenendigungen gebildet werden; die Einheiten der verschiedenen Präparate sind nicht austauschbar.","nebenwirkungen":{"sehrHaeufig":["Hängendes Oberlid (Ptosis) bei Behandlung des Lidkrampfs","Harnwegsinfekte nach Injektion in die Blase"],"haeufig":["Schmerzen, Bluterguss oder Rötung an der Einstichstelle","Muskelschwäche in der Umgebung der Injektionsstelle","Schluckbeschwerden (Dysphagie) nach Injektionen im Halsbereich","Kopf- und Nackenschmerzen","Harnverhalt nach Injektion in die Blase (Katheterisierung kann nötig werden)","Trockene oder gereizte Augen, Tränenfluss nach Injektion im Augenbereich"],"unbekannt":["Ausbreitung der Wirkung fern der Injektionsstelle mit allgemeiner Muskelschwäche, Doppelbildern, Schluck- und Atemstörungen (in Einzelfällen tödlich)","Aspirationspneumonie (Lungenentzündung durch Verschlucken)","Anaphylaxie und andere schwere allergische Reaktionen","Herzrhythmusstörungen und Herzinfarkt bei Herzvorerkrankungen","Engwinkelglaukom nach Behandlung im Augenbereich"]},"schwangerschaft":"Nicht empfohlen; Anwendung nur, wenn unbedingt nötig. Ästhetische Behandlungen in der Schwangerschaft unterlassen.","stillzeit":"Nicht empfohlen, da unbekannt ist, ob der Wirkstoff in die Muttermilch übergeht.","hinweise":["Nur von erfahrenen Ärztinnen und Ärzten anwenden lassen; die Einheiten der verschiedenen Präparate sind nicht austauschbar.","Bei Schluck-, Sprech- oder Atembeschwerden nach der Injektion sofort ärztliche Hilfe holen.","Die Wirkung setzt nach einigen Tagen ein und hält meist 3–6 Monate.","Muskelschwäche, hängende Lider oder Sehstörungen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"brimonidin":{"wirkmechanismus":"Senkt den Augeninnendruck bzw. verengt die erweiterten Hautgefässe. Brimonidin stimuliert Alpha-2-Adrenozeptoren: Im Auge vermindert es die Bildung von Kammerwasser und verbessert dessen Abfluss über den uveoskleralen Weg. In der Haut zieht es die oberflächlichen Blutgefässe zusammen und reduziert so die Rötung für einige Stunden. Gelangt es in den Kreislauf, kann es Blutdruck und Puls senken und müde machen.","nebenwirkungen":{"sehrHaeufig":["Augentropfen: Augenrötung, Brennen, Stechen, Juckreiz, Fremdkörpergefühl","Augentropfen: allergische Bindehautentzündung (oft verzögert nach Monaten)","Augentropfen: Mundtrockenheit, Müdigkeit, Schläfrigkeit, Kopfschmerzen","Verschwommenes Sehen"],"haeufig":["Augentropfen: Lidschwellung, Lichtempfindlichkeit, Hornhautschäden","Schwindel, Geschmacksstörungen","Magen-Darm-Beschwerden, Schwächegefühl","Gel: Rötung, Flush, Juckreiz, Brennen der Haut"],"gelegentlich":["Herzklopfen, Herzrhythmusstörungen","Depression","Gel: Verschlechterung der Rosazea, Hautreizung, Kältegefühl der Haut","Nasentrockenheit"],"selten":["Atemnot","Gel: Angioödem (Schwellung)"],"sehrSelten":["Ohnmacht (Synkope), Blutdruckabfall oder -anstieg","Regenbogenhautentzündung (Iritis), Pupillenverengung"],"unbekannt":["Bradykardie (langsamer Puls)","Allergische Hautreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; beim Menschen nicht ausreichend untersucht.","stillzeit":"Augentropfen sollen in der Stillzeit nicht angewendet werden; auch das Gel wird nicht empfohlen.","hinweise":["Kann müde machen und die Sicht kurz verschwimmen lassen – Vorsicht beim Autofahren.","Augentropfen: nach dem Eintropfen den inneren Augenwinkel 1–2 Minuten zudrücken; zu anderen Augentropfen 5 Minuten Abstand.","Gel: nur erbsengrosse Menge einmal täglich im Gesicht verteilen, Augen und Lippen aussparen, danach Hände waschen."],"darreichung":["Augentropfen","Gel"]},"brimonidin-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei Wege. Brimonidin, ein selektiver Alpha-2-Rezeptor-Agonist, vermindert die Kammerwasserbildung und verbessert den Abfluss über den uveoskleralen Weg. Timolol, ein nicht selektiver Betablocker, drosselt die Kammerwasserproduktion im Ziliarkörper. Beide Wirkstoffe können nach Aufnahme in den Kreislauf auch Blutdruck, Puls und Wachheit beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Augenrötung (Bindehauthyperämie)","Brennen im Auge"],"haeufig":["Allergische Bindehautentzündung, Bindehautfollikel","Augenjucken, Stechen, Fremdkörpergefühl, trockenes Auge, Tränenfluss, Augenausfluss","Oberflächliche Hornhautentzündung, Hornhauterosion, Lidrandentzündung","Lidschwellung, -rötung und -juckreiz, Sehstörungen","Schläfrigkeit, Kopfschmerzen, Depression","Mundtrockenheit, Schwäche (Asthenie)","Bluthochdruck"],"gelegentlich":["Herzinsuffizienz, Herzrhythmusstörungen","Schwindel, Ohnmacht (Synkope)","Schnupfen, trockene Nase","Übelkeit, Geschmacksstörungen"],"unbekannt":["Langsamer Puls (Bradykardie), Blutdruckabfall","Bronchospasmus, Atemnot","Allergische Haut- und Allgemeinreaktionen","Müdigkeit, Schlafstörungen"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen (langsamer Puls, Unterzuckerung) überwachen.","stillzeit":"Timolol geht in die Muttermilch über, Brimonidin vermutlich ebenfalls – in der Stillzeit nicht anwenden.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Kann müde machen und die Sicht kurz trüben – Vorsicht beim Autofahren; Alkohol meiden.","Bei Asthma, Herzkrankheiten, Depression oder vor einer Operation die Anwendung ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"brinzolamid":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Brinzolamid hemmt die Carboanhydrase II im Ziliarkörper; dadurch wird weniger Bicarbonat gebildet und der Flüssigkeitstransport ins Augeninnere verlangsamt. Ein Teil gelangt in den Kreislauf und reichert sich in den roten Blutkörperchen an; eine relevante Wirkung auf den Säure-Basen-Haushalt ist bei Augentropfen aber selten. Chemisch ist Brinzolamid ein Sulfonamid.","nebenwirkungen":{"haeufig":["Bitterer oder ungewöhnlicher Geschmack (Dysgeusie)","Verschwommenes Sehen","Augenreizung, Augenschmerzen, Fremdkörpergefühl","Augenrötung"],"gelegentlich":["Hornhautentzündung und -schäden (Keratitis, Erosion)","Trockenes Auge, Augenjucken, Lidrandentzündung, Bindehautentzündung, Lichtempfindlichkeit","Kopfschmerzen, Schwindel, Schläfrigkeit","Übelkeit, Durchfall, Mundtrockenheit","Nasenbluten, Rachenreizung, Atemnot"],"unbekannt":["Überempfindlichkeitsreaktionen","Ohrgeräusche (Tinnitus)","Herzrhythmusstörungen, Herzrasen","Haarausfall, Hautausschlag","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"]},"schwangerschaft":"Keine ausreichenden Daten, im Tierversuch fruchtschädigend. Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung verhüten.","stillzeit":"Nicht bekannt, ob Brinzolamid in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Vor Gebrauch gut schütteln.","Nach dem Eintropfen das Auge schliessen oder den inneren Augenwinkel 1–2 Minuten sanft zudrücken.","Bei mehreren Augentropfen mindestens 5 Minuten Abstand halten; Kontaktlinsen vorher herausnehmen."],"darreichung":["Augentropfen (Suspension)"]},"brinzolamid-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem die Bildung von Kammerwasser auf zwei Wegen gedrosselt wird. Brinzolamid hemmt die Carboanhydrase II im Ziliarkörper und vermindert so die Bicarbonat- und Flüssigkeitsbildung. Timolol, ein nicht selektiver Betablocker, verringert die Kammerwasserproduktion zusätzlich. Ein Teil beider Wirkstoffe gelangt in den Kreislauf; vor allem Timolol kann Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"haeufig":["Verschwommenes Sehen","Augenschmerzen, Augenreizung, Fremdkörpergefühl","Geschmacksstörung (bitterer Geschmack)"],"gelegentlich":["Hornhautentzündung und Hornhauterosion, trockenes Auge","Augenrötung, Augenausfluss, Augenjucken, Lidrandentzündung","Blutdruckabfall","Husten, Rachenschmerzen, Fliessschnupfen"],"unbekannt":["Langsamer Puls (Bradykardie), Herzrhythmusstörungen, Herzinsuffizienz","Bronchospasmus, Atemnot, Asthma","Schwindel, Kopfschmerzen, Müdigkeit, Depression","Kalte Hände und Füsse","Allergische Reaktionen, Hautausschlag","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"]},"schwangerschaft":"Nicht anwenden, ausser es ist ärztlich klar notwendig (Brinzolamid im Tierversuch fruchtschädigend). Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen überwachen.","stillzeit":"Timolol geht in die Muttermilch über; ein Risiko für den Säugling ist nicht auszuschliessen. Ärztlich abwägen, ob abgestillt oder die Behandlung unterbrochen wird.","hinweise":["Vor Gebrauch gut schütteln.","Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen (Suspension)"]},"brivudin":{"wirkmechanismus":"Hemmt die Vermehrung des Varizella-Zoster-Virus, das Windpocken und Gürtelrose verursacht. Brivudin ist ein Thymidin-Analogon, das in infizierten Zellen bevorzugt durch die virale Thymidinkinase phosphoryliert wird; das entstehende Brivudin-Triphosphat hemmt die virale DNA-Polymerase und damit die Bildung neuer Virus-DNA. Das Abbauprodukt Bromovinyluracil hemmt irreversibel das Enzym Dihydropyrimidin-Dehydrogenase (DPD), das Fluoropyrimidine wie 5-Fluorouracil abbaut – daher die lebensgefährliche Wechselwirkung mit diesen Krebsmitteln.","nebenwirkungen":{"haeufig":["Übelkeit"],"gelegentlich":["Kopfschmerzen, Schwindel, Schläfrigkeit","Schlaflosigkeit, Angstgefühle","Erbrechen, Durchfall, Verdauungsbeschwerden, Bauchschmerzen, Verstopfung","Appetitlosigkeit","Erhöhte Leberwerte, Fettleber","Hautausschlag, Juckreiz, Überempfindlichkeitsreaktionen","Veränderungen des Blutbilds (z. B. weniger Granulozyten, Anämie, Eosinophilie)","Müdigkeit, Schwäche"],"selten":["Hepatitis (Leberentzündung), Bilirubinanstieg","Verwirrtheit, Halluzinationen","Geschmacksstörungen","Blutdruckabfall","Thrombozytopenie (Mangel an Blutplättchen)","Knochenschmerzen"],"unbekannt":["Schwere Leberschäden bis zum akuten Leberversagen (Einzelfälle)","Schwere Hautreaktionen"]},"schwangerschaft":"In der Schwangerschaft kontraindiziert (keine ausreichenden Erfahrungen).","stillzeit":"In der Stillzeit kontraindiziert.","hinweise":["Einmal täglich möglichst zur gleichen Tageszeit während 7 Tagen einnehmen; die Behandlung nicht verlängern.","Vor der Einnahme unbedingt angeben, ob eine Krebsbehandlung läuft, geplant ist oder kürzlich stattfand – auch 5-Fluorouracil-Cremes gegen Hautveränderungen zählen.","Mit Fluoropyrimidinen (z. B. Capecitabin) frühestens 4 Wochen nach der letzten Brivudin-Tablette beginnen."],"darreichung":["Tabletten"]},"bromazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend und muskelentspannend, indem es die hemmenden Signale im Gehirn verstärkt. Bromazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die Wirkung des hemmenden Botenstoffs GABA (vermehrter Chlorid-Einstrom, verminderte Erregbarkeit der Nervenzellen). In höheren Dosen wirkt es auch schlaffördernd und krampflösend. Die Halbwertszeit beträgt etwa 20 Stunden.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit und verminderte Aufmerksamkeit (auch am Folgetag)","Muskelschwäche, Gangunsicherheit (Ataxie), Stürze","Schwindel, Kopfschmerzen, Doppeltsehen","Verwirrtheit, Gedächtnislücken (anterograde Amnesie)","Paradoxe Reaktionen wie Unruhe, Reizbarkeit, Aggressivität, Albträume, Halluzinationen","Abhängigkeit; Entzugs- und Absetzsymptome (Schlaflosigkeit, Angst, Krampfanfälle)","Atemdepression (abgeschwächte Atmung)","Magen-Darm-Beschwerden, Hautreaktionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, besonders im ersten Drittel. Bei Einnahme gegen Ende der Schwangerschaft oder unter der Geburt drohen beim Neugeborenen Muskelschlaffheit, Trinkschwäche, Unterkühlung, Atemprobleme und Entzugssymptome.","stillzeit":"Bromazepam geht in die Muttermilch über; während der Einnahme soll nicht gestillt werden.","hinweise":["Kann die Fahrtüchtigkeit und das Reaktionsvermögen stark beeinträchtigen – auch noch am nächsten Tag.","Keinen Alkohol trinken: verstärkte Dämpfung.","Möglichst kurz anwenden (in der Regel höchstens 8–12 Wochen inklusive Ausschleichen), da sich eine Abhängigkeit entwickeln kann.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anleitung schrittweise reduzieren."],"darreichung":["Tabletten"]},"bromhexin":{"wirkmechanismus":"Verflüssigt zähen Bronchialschleim und erleichtert das Abhusten. Bromhexin ist ein synthetischer Abkömmling des Pflanzenstoffs Vasicin; es lockert die Faserstruktur des Schleims (Sekretolyse) und fördert den Abtransport durch die Flimmerhärchen. Im Körper wird es unter anderem zu Ambroxol umgewandelt, das zur Wirkung beiträgt.","nebenwirkungen":{"gelegentlich":["Übelkeit, Erbrechen, Durchfall, Oberbauchschmerzen","Fieber"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)"],"unbekannt":["Anaphylaxie bis zum Schock, Angioödem, Juckreiz","Bronchospasmus (Verkrampfung der Atemwege)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, akute generalisierte exanthematische Pustulose)"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Ein Übergang in die Muttermilch ist zu erwarten; in der Stillzeit nicht empfohlen.","hinweise":["Nicht mit Hustenstillern kombinieren.","Viel trinken unterstützt die Schleimlösung.","Bei neuem Hautausschlag oder Blasen an Haut und Schleimhäuten sofort absetzen und ärztlich abklären lassen."],"darreichung":["Tabletten","Sirup"]},"budesonid":{"wirkmechanismus":"Dämpft Entzündungen direkt dort, wo es angewendet wird – im Darm, in der Speiseröhre, in den Bronchien oder in der Nase. Budesonid ist ein stark wirksames Glukokortikoid, das an den Glukokortikoidrezeptor in den Zellen bindet und die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) sowie die Einwanderung von Entzündungszellen hemmt. Nach dem Schlucken werden rund 85–90 % beim ersten Durchgang durch die Leber über CYP3A4 abgebaut, deshalb sind Kortison-Nebenwirkungen im ganzen Körper deutlich seltener als etwa bei Prednison. Spezielle Darreichungen setzen den Wirkstoff gezielt im Dünndarm oder Dickdarm frei.","nebenwirkungen":{"haeufig":["Pilzinfektion (Soor) in Mund und Rachen bei Inhalation bzw. in der Speiseröhre bei Schmelztabletten","Heiserkeit, Rachenreizung und Husten (Inhalation)","Nasenbluten und Reizung der Nasenschleimhaut (Nasenspray)","Kortisontypische Veränderungen wie Vollmondgesicht (bei Einnahme)","Hypokaliämie (Kaliummangel) bei Einnahme","Verdauungsbeschwerden, Muskelkrämpfe, Herzklopfen","Nervosität, Schlafstörungen, Stimmungsschwankungen","Hautausschlag, Nesselsucht"],"gelegentlich":["Angst, Zittern (Tremor), Depression","Verschwommenes Sehen"],"selten":["Grauer Star (Katarakt), grüner Star (Glaukom)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege nach Inhalation)","Blaue Flecken","Verhaltensänderungen und Aggressivität, besonders bei Kindern","Unterdrückung der Nebennierenfunktion"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Wachstumsverzögerung bei Kindern","Abnahme der Knochendichte","Durchbruch der Nasenscheidewand (Nasenspray)"],"unbekannt":["Chorioretinopathia centralis serosa (Netzhauterkrankung mit Sehstörung)"]},"schwangerschaft":"Inhaliertes Budesonid ist gut untersucht und kann in der Schwangerschaft angewendet werden. Zum Einnehmen nur nach ärztlicher Abwägung.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; Inhalation in üblicher Dosis vertretbar, Einnahme nach ärztlicher Abwägung.","hinweise":["Nach dem Inhalieren den Mund mit Wasser ausspülen oder die Zähne putzen (beugt Soor und Heiserkeit vor).","Zur Inhalation regelmässig anwenden, auch ohne Beschwerden; im akuten Asthmaanfall das Notfallspray benutzen.","Kapseln und Tabletten unzerkaut schlucken; während der Behandlung keinen Grapefruitsaft trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anweisung ausschleichen."],"darreichung":["Kapseln (magensaftresistent bzw. mit verzögerter Freisetzung)","Retardtabletten","Schmelztabletten","Rektalschaum","Klysma (Einlauf)","Pulver zur Inhalation","Suspension zur Inhalation (Vernebler)","Nasenspray"]},"bumetanid":{"wirkmechanismus":"Schwemmt rasch und kräftig Wasser aus, indem es die Salzausscheidung über die Niere steigert. Bumetanid hemmt im aufsteigenden Teil der Henle-Schleife den Natrium-Kalium-2-Chlorid-Kotransporter, sodass grosse Mengen Natrium, Chlorid und Wasser ausgeschieden werden; auch Kalium, Magnesium und Calcium gehen vermehrt verloren. Die Wirkung setzt nach Einnahme innert etwa einer Stunde ein und hält einige Stunden an; gewichtsbezogen ist Bumetanid etwa 40-mal stärker als Furosemid.","nebenwirkungen":{"haeufig":["Hypokaliämie (Kaliummangel)","Hyponatriämie und Hypochlorämie (Natrium- und Chloridmangel)","Dehydratation (Flüssigkeitsmangel)","Hyperurikämie (erhöhte Harnsäure)","Schwindel, Kopfschmerzen, Müdigkeit","Blutdruckabfall beim Aufstehen"],"unbekannt":["Muskelkrämpfe","Hyperglykämie (erhöhter Blutzucker), Gichtanfall","Hörstörungen, Ohrensausen","Thrombozytopenie und andere Blutbildveränderungen","Schwere Hautreaktionen","Gynäkomastie (Brustvergrösserung beim Mann)","Akuter Harnverhalt","Akutes Nierenversagen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; nicht zur Behandlung von Schwangerschaftsödemen oder Schwangerschaftshochdruck (verminderte Durchblutung der Plazenta).","stillzeit":"Nicht empfohlen; kann die Milchbildung hemmen.","hinweise":["Morgens bzw. tagsüber einnehmen; die Wirkung setzt rasch ein.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren; Körpergewicht beobachten.","Bei Schwindel, starkem Durst, Muskelkrämpfen oder Hörstörungen ärztlich melden.","Bei Durchfall, Erbrechen oder starkem Schwitzen droht Flüssigkeitsmangel – ärztlich abklären."],"darreichung":["Tabletten","Injektionslösung"]},"bupivacain":{"wirkmechanismus":"Betäubt örtlich, indem es die Weiterleitung von Nervensignalen – auch von Schmerzsignalen – vorübergehend unterbricht. Bupivacain blockiert die spannungsabhängigen Natriumkanäle der Nervenmembran und verhindert so die Entstehung und Fortleitung von Aktionspotenzialen. Die Wirkung setzt langsam ein, hält aber mehrere Stunden an. Gelangt zu viel davon ins Blut, blockiert es auch Natriumkanäle im Herzen und im Gehirn, was Herzrhythmusstörungen und Krampfanfälle auslösen kann.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall)","Übelkeit"],"haeufig":["Kribbeln (Parästhesien), Schwindel","Bradykardie (langsamer Puls)","Blutdruckanstieg","Erbrechen","Harnverhalt"],"gelegentlich":["Zeichen einer Vergiftung des Nervensystems: Taubheit um den Mund, Ohrgeräusche, Sehstörungen, Zittern, Krampfanfälle, Bewusstlosigkeit"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Herzrhythmusstörungen, Herzstillstand","Nervenschäden, Lähmungen bis Querschnittlähmung, Arachnoiditis (Entzündung der Rückenmarkshäute)","Atemdepression","Doppeltsehen"]},"schwangerschaft":"Wird seit Jahrzehnten in der Geburtshilfe eingesetzt; im ersten Schwangerschaftsdrittel nur nach Abwägung. Die 0,75-%-Lösung ist für die Periduralanästhesie unter der Geburt kontraindiziert.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist möglich.","hinweise":["Nach einer rückenmarknahen Betäubung können Gefühl und Kraft in den Beinen über Stunden fehlen – nur mit Hilfe aufstehen.","Blutverdünnende Medikamente vor dem Eingriff unbedingt angeben.","Taubheit um den Mund, Ohrensausen, Metallgeschmack oder Unruhe sofort melden (mögliche Zeichen einer Überdosierung)."],"darreichung":["Injektionslösung","Hyperbare Injektionslösung (Spinalanästhesie)"]},"buprenorphin":{"wirkmechanismus":"Lindert Schmerzen und unterdrückt bei Opioidabhängigkeit das Verlangen und die Entzugssymptome. Buprenorphin ist ein Partialagonist am μ-Opioidrezeptor und ein Antagonist am κ-Rezeptor; es bindet sehr fest an den Rezeptor und löst sich nur langsam. Dadurch ist die Atemdämpfung bei alleiniger Anwendung begrenzt («Ceiling-Effekt»), doch es kann die Wirkung anderer Opioide abschwächen und bei Opioidabhängigen einen Entzug auslösen. Der Abbau erfolgt in der Leber über CYP3A4 zu Norbuprenorphin.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schlaflosigkeit","Starkes Schwitzen","Rötung und Juckreiz an der Pflasterstelle","Entzugssymptome (bei Substitution)"],"haeufig":["Schwindel, Schläfrigkeit","Verstopfung, Erbrechen, Bauchschmerzen","Angst, Unruhe, Depression","Atemnot","Blutdruckabfall beim Aufstehen, Ohnmacht","Wassereinlagerungen, Müdigkeit, Schwäche","Muskel- und Gelenkschmerzen"],"selten":["Atemdepression (abgeschwächte Atmung)"],"unbekannt":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Hepatitis, Leberversagen, Gelbsucht","Halluzinationen","Abhängigkeit","Entzugssyndrom beim Neugeborenen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; eine bestehende Substitutionsbehandlung wird in der Regel weitergeführt. Gegen Ende der Schwangerschaft Gefahr von Atemdepression und Entzugssyndrom beim Neugeborenen.","stillzeit":"Buprenorphin geht in geringen Mengen in die Muttermilch über. Unter Substitution ist Stillen nach ärztlicher Abwägung möglich; bei Schmerzbehandlung mit dem Pflaster wird vom Stillen abgeraten.","hinweise":["Sublingualtabletten unter der Zunge vollständig zergehen lassen, nicht schlucken oder kauen.","Kein Alkohol und keine Beruhigungsmittel ohne ärztliche Absprache – Gefahr lebensbedrohlicher Atemdämpfung; die Fahrtüchtigkeit kann eingeschränkt sein.","Pflaster keiner Wärme aussetzen; gebrauchte Pflaster gefaltet und für Kinder unerreichbar entsorgen.","Bei Substitution Leberwerte regelmässig kontrollieren."],"darreichung":["Sublingualtabletten","Transdermale Pflaster","Injektionslösung","Depot-Injektionslösung"]},"bupropion":{"wirkmechanismus":"Wirkt antriebssteigernd und stimmungsaufhellend, indem es die Botenstoffe Noradrenalin und Dopamin im Gehirn länger wirken lässt. Bupropion und sein wichtigster aktiver Abbaustoff Hydroxybupropion (gebildet über CYP2B6) hemmen die Wiederaufnahme von Noradrenalin und Dopamin in die Nervenzellen; auf Serotonin wirken sie kaum. Bei der Raucherentwöhnung mildert es vermutlich über das Belohnungssystem Rauchverlangen und Entzugssymptome. Bupropion ist zudem ein starker Hemmer des Leberenzyms CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen","Mundtrockenheit","Übelkeit, Erbrechen"],"haeufig":["Agitiertheit (Unruhe), Angst","Zittern (Tremor), Schwindel, Geschmacksstörungen","Appetitlosigkeit","Blutdruckanstieg (teils deutlich), Hautrötung (Flush)","Bauchschmerzen, Verstopfung","Hautausschlag, Juckreiz, Schwitzen","Sehstörungen, Ohrensausen (Tinnitus)","Fieber, Brustschmerzen, Schwäche"],"gelegentlich":["Depression, Verwirrtheit","Konzentrationsstörungen","Herzrasen (Tachykardie)","Gewichtsabnahme"],"selten":["Krampfanfälle (etwa 1 von 1000 Behandelten)"],"sehrSelten":["Schwere Überempfindlichkeitsreaktionen (Angioödem, Atemnot, anaphylaktischer Schock, Serumkrankheit-ähnliche Reaktionen)","Halluzinationen, Aggressivität, Wahnvorstellungen, Albträume","Erythema multiforme, Stevens-Johnson-Syndrom","Hepatitis, Gelbsucht, erhöhte Leberwerte","Blutzuckerschwankungen","Herzklopfen, Ohnmacht"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Psychose","Hyponatriämie (Natriummangel)","Serotoninsyndrom (zusammen mit serotonergen Mitteln)","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; einige Studien weisen auf ein möglicherweise erhöhtes Risiko für angeborene Herzfehler hin. Zur Raucherentwöhnung in der Schwangerschaft nicht anwenden.","stillzeit":"Bupropion und seine Abbauprodukte gehen in die Muttermilch über; nur nach ärztlicher Abwägung (abstillen oder auf die Behandlung verzichten).","hinweise":["Retardtabletten ganz schlucken, nicht teilen, zerkauen oder zerdrücken (höheres Risiko für Krampfanfälle).","Höchstdosis nicht überschreiten; bei zweimal täglicher Einnahme (Raucherentwöhnung) mindestens 8 Stunden Abstand halten und nicht kurz vor dem Schlafengehen einnehmen.","Zur Raucherentwöhnung das Rauchstopp-Datum in der zweiten Behandlungswoche festlegen.","Blutdruck regelmässig kontrollieren; Alkohol meiden."],"darreichung":["Retardtabletten"]},"butamirat":{"wirkmechanismus":"Dämpft den Hustenreflex. Butamirat wirkt zentral auf das Hustenzentrum im Hirnstamm; chemisch ist es weder mit Opioiden noch mit Opium-Alkaloiden verwandt und hat kein bekanntes Abhängigkeitspotenzial. Zusätzlich werden eine leicht bronchienerweiternde und entzündungshemmende Wirkung beschrieben.","nebenwirkungen":{"selten":["Schläfrigkeit","Schwindel","Übelkeit, Durchfall","Hautausschlag, Nesselsucht"]},"schwangerschaft":"Im 1. Drittel nicht anwenden; danach nur nach ärztlicher Abwägung (keine ausreichenden Daten).","stillzeit":"Nicht bekannt, ob Butamirat in die Muttermilch übergeht; vorsichtshalber nicht anwenden.","hinweise":["Nicht gleichzeitig mit Schleimlösern einnehmen.","Nur kurzfristig bei trockenem Reizhusten; bei Husten länger als eine Woche, Fieber oder Atemnot ärztlich abklären lassen.","Kann müde machen – Vorsicht beim Autofahren, Alkohol meiden."],"darreichung":["Sirup","Tropfen"]},"butylscopolamin":{"wirkmechanismus":"Entspannt die verkrampfte glatte Muskulatur von Magen, Darm, Gallen- und Harnwegen. Butylscopolamin blockiert Muskarinrezeptoren an der glatten Muskulatur und in den vegetativen Ganglien der Bauchorgane. Als quartäre Ammoniumverbindung wird es aus dem Darm nur zu weniger als 1 % aufgenommen und gelangt praktisch nicht ins Gehirn; zentrale Nebenwirkungen wie bei Atropin oder Scopolamin sind daher kaum zu erwarten.","nebenwirkungen":{"haeufig":["Akkommodationsstörungen (Sehstörungen) (Injektion)","Schwindel (Injektion)","Tachykardie (Herzrasen) (Injektion)","Mundtrockenheit"],"gelegentlich":["Hautreaktionen wie Ausschlag und Juckreiz","Störungen der Schweissbildung (Dyshidrose)"],"selten":["Harnverhalt"],"unbekannt":["Anaphylaxie bis zum anaphylaktischen Schock, nach Injektion auch mit tödlichem Ausgang","Atemnot (Dyspnoe)","Blutdruckabfall, Hautrötung (Flush) (Injektion)","Pupillenerweiterung und erhöhter Augeninnendruck (Injektion)","Nesselsucht (Urtikaria)"]},"schwangerschaft":"Es liegen nur begrenzte Erfahrungen vor; vorsichtshalber in der Schwangerschaft vermeiden bzw. nur nach ärztlicher Abwägung anwenden.","stillzeit":"Ob Butylscopolamin in die Muttermilch übergeht, ist nicht ausreichend untersucht; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Dragées unzerkaut mit Wasser einnehmen.","Ohne ärztlichen Rat nicht länger als einige Tage anwenden; bei unklaren, starken oder anhaltenden Bauchschmerzen ärztlich abklären.","Nach einer Injektion kann das Sehen vorübergehend gestört sein: bis zur Normalisierung nicht Auto fahren."],"darreichung":["Dragées","Injektionslösung"]}});
